import sys
from collections import defaultdict

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    count = 0
    prefix_ones = [0] * (n + 1)

    for i in range(n):
        prefix_ones[i + 1] = prefix_ones[i] + (s[i] == '1')

    for i in range(n):
        for j in range(i + 1, n + 1):
            num_ones = prefix_ones[j] - prefix_ones[i]
            if num_ones > 0 and (j - i) % num_ones == 0:
                count += 1

    print(count)

main()
